import requests
from bs4 import BeautifulSoup
from urllib.parse import urlparse

class WebScraper:
    def __init__(self, url):
        if not self._is_valid_url(url):
            raise ValueError('Invalid URL provided')
        self.url = url

    def _is_valid_url(self, url):
        try:
            result = urlparse(url)
            return all([result.scheme, result.netloc])
        except Exception:
            return False

    def fetch(self):
        try:
            response = requests.get(self.url, timeout=10)
            response.raise_for_status()
            return response.text
        except requests.RequestException as e:
            raise RuntimeError(f'Failed to fetch {self.url}: {e}')

    def extract_headings(self):
        html = self.fetch()
        soup = BeautifulSoup(html, 'html.parser')
        return [tag.get_text(strip=True) for tag in soup.find_all(['h1', 'h2', 'h3', 'h4', 'h5', 'h6'])]

request_counts = {}
def allow_request(ip, limit=3):
    current = request_counts.get(ip, 0)
    if current >= limit:
        return False
    request_counts[ip] = current + 1
    return True
print(allow_request("192.168.1.1"))

def get_backoff_delay(attempt, base_delay=1):
    return base_delay * (2 ** attempt)

print([get_backoff_delay(i) for i in range(4)])

